"fpkg.source": "Játékforrás",
"fpkg.sourcePlaceholder": "/games/PPSA09519.exfat, /games/my-game, /games/game.ffpkg",
"fpkg.output": "Kimeneti mappa",
"fpkg.outputHint": "Alapértelmezett: ~/Downloads/fpkgs",
"fpkg.free": "Szabad",
"fpkg.cancel": "Mégse",
"fpkg.done": "Csomag megírva",
"fpkg.error": "Átalakítási hiba",
// Az Átalakítás képernyő nyíltan közli, hogy nem kész. A képernyőn
// belül maradt, nem csak a Beállítások kapcsoló mögött: a kapcsoló
// azt magyarázza, miért jelent meg a bejegyzés, nem azt, hogy mi
// történik egy vele átalakított játékkal.
"fpkg.about": "Mutass rá egy játékmappára, vagy egy .exfat vagy .ffpkg csatolási képre. Az átalakító beolvassa a fát, ellenőrzi, hogy megvan-e minden, amire egy indítható csomagnak szüksége van, és ír egy debug-formátumú .pkg-t a kimeneti mappába.",
"fpkg.aboutWhere": "Az átalakítás a motort futtató gépen fut — ezen a számítógépen, egy Docker hoston vagy egy Android eszközön — nem a konzolon. Semmi nem éri el a konzolt, amíg meg nem nyomod a Telepítést, és a telepítés a csomagot átstreameli ahelyett, hogy előbb egy másolatot staged-elne belőle.",
"fpkg.aboutSource": "A forrásnak egy már visszafejtett játékfának kell lennie. Egy retail telepítés itt nem csomagolható ki, és az alábbi ellenőrzés jelzi, ha ezt választottad.",
"fpkg.aboutChecks": "Mit vizsgál az ellenőrzés",
"fpkg.checkEboot": "Egy eboot.bin a fa gyökerében — a cím modulja. Nyers ELF-nek vagy becsomagolt SELF-nek kell lennie; egy retail-aláírt modul nem csomagolható újra.",
"fpkg.checkParam": "sce_sys/param.json, és nincs sce_sys/param.sfo — a param.sfo a konzol indítási útvonalát a PS4 útvonal felé tereli.",
"fpkg.checkIcons": "Egy 36 karakteres content id, mindkét ikon, és a jogosultsági modul sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Hogy a csomag DRM értéke szabványos. Egy ingyenes vagy frissíthető érték zárolja a konzolt a cím körül; ez csak a csomagban kerül átírásra, a saját fájlodat sosem érinti.",

