library_mount_modal_usb_warn_body: "A /mnt/usb* és /mnt/ext* a PS5 kernel USB hotplug névterébe tartoznak; egy kép csatolása oda a legtöbb firmware-en kernel-szabállyal blokkolva van. Ha ez sikertelen „Operation not permitted” hibával, válts a /mnt/ps5upload (a payload saját csatolási gyökere) vagy a /data mappára — mindkettő működik kernelpatch nélkül.",
