nanodns: "nanoDNS",
nanodns_not_loaded_title: "A nanoDNS még nincs beállítva",
nanodns_not_loaded_body:
  "Nincs /data/nanodns/nanodns.ini a konzolon — töltsd be egyszer a nanoDNS-t a Payloadok fülről (első futáskor alapértelmezett konfigot ír), majd gyere vissza a szerkesztéshez.",
nanodns_dns_howto_title: "Irányítsd a PS5 DNS-ét a nanoDNS-re",
nanodns_dns_howto_body:
  "A PS5-ön: Beállítások → Hálózat → Internetkapcsolat beállítása → (a kapcsolatod) → Egyéni → DNS beállítások → Kézi. Állítsd az Elsődleges DNS-t a lenti /data/nanodns/nanodns.ini fájl [general] szekciójának bind beállításából származó címre — például bind=127.0.0.1 esetén az Elsődleges DNS legyen 127.0.0.1.",
nanodns_save_error: "Nem sikerült menteni",
nanodns_saved: "nanoDNS konfig mentve",
nanodns_saved_body:
  "Töltsd be újra (küldd el újra) a nanoDNS-t a Payloadok fülről, hogy a módosítások érvénybe lépjenek.",
nanodns_revert: "Visszaállítás",
nanodns_save: "Mentés",
nanodns_apply_hint:
  "Szekciók: [general] (log/debug/bind) · [upstream] (server×N, timeout_ms) · [overrides] (mask=IPv4, 0.0.0.0 = blokkolás) · [exceptions] (egy mask soronként). Mentéskor kiírja a fájlt; töltsd be újra a nanoDNS-t a Payloadokból az alkalmazáshoz.",
nanodns_version_modern:
  "A futásidejű naplóból felismerve. Az IPv6 és a csendes mód támogatott.",
nanodns_version_legacy:
  "A futásidejű naplóból felismerve. Ez a 0.3-as payload IPv4 beállításokat használ; a csendes mód és a bind6 nem alkalmazódik.",
nanodns_version_config:
  "A futásidejű banner nem volt elérhető, de ez a fájl 0.4-es beállításokat tartalmaz. Töltsd újra a nanoDNS 0.4-et az IPv6 és a csendes mód használatához.",
nanodns_version_unknown:
  "Nem található futásidejű banner vagy 0.4-es beállítás. A szerkesztő 0.3-kompatibilis módban marad, amíg a nanoDNS 0.4 fel nem ismerhető.",
nanodns_migrate_body:
  "Megtartja minden egyedi resolvered, felülírásod, kivételed, megjegyzésed és útvonalad; csak a hiányzó nanoDNS 0.4 beállításokat adja hozzá, és kijavítja az elavult Yandex.DNS címet. Nézd át a szerkesztőben, majd Mentsd.",
nanodns_yandex_body:
  "A nanoDNS 0.3 tévedésből a 77.77.88.88-at szállította. A 77.88.8.8-ra javítás biztonságos mind 0.3, mind 0.4 esetén, és a fájl többi része változatlan marad.",
nanodns_quiet_hint:
  "Leállítja a nanoDNS indítási felugró ablakait; a naplózás rendben folytatódik.",
nanodns_quiet_label: "Csendes mód",
nanodns_bind6_hint:
  "Használd a ::1-et ehhez a konzolhoz, a ::-t minden IPv6 interfészhez, vagy az off-ot az IPv6 letiltásához.",
nanodns_bind6_label: "IPv6 bind cím",
