about_disclaimer_purpose:
  "A ps5upload kizárólag kutatási, oktatási, interoperabilitási és homebrew-fejlesztési célra készült. Nem áll kapcsolatban a Sony Interactive Entertainment Inc.-vel, és nem is támogatja az. A „PlayStation” és a „PS5” a Sony Interactive Entertainment Inc. védjegye, itt kizárólag azonosítás céljából szerepel.",
about_disclaimer_risk:
  "Ez a szoftver „ahogy van” alapon, mindenféle garancia nélkül készül. Egy módosított konzol üzemeltetése tartósan károsíthatja azt, visszafordíthatatlanul megsemmisítheti a mentéseket és licenceket, és a fiókod vagy konzolod kitiltásához vezethet. A használat teljes egészében a te saját felelősséged. Mentsd el előre azt, amit nem engedhetsz meg magadnak, hogy elveszítsd.",
about_disclaimer_piracy:
  "Csak olyan hardveren és tartalommal használd, ami a sajátod, és amire jogod van. Nem használható olyan szoftver másolására, terjesztésére vagy futtatására, amihez nincs jogosultságod.",
