library_images_capabilities: "Csatold a játék indításához, vagy szerkeszd a fájlokat a tartalom módosításához — DLC hozzáadása, eszközök cseréje vagy backport patch alkalmazása. A módosítások közvetlenül a képbe íródnak.",

library_edit_modal_title: "\"{name}\" szerkesztése",
library_edit_modal_intro: "Válaszd ki, hova csatoljuk, amíg dolgozol. A munka idejére kikerül a ShadowMount+-ból, és a befejezéskor visszakerül — így addig rejtve van a játék a PS5 főképernyőjén.",
