helper_mismatch_title: "A PS5 segédprogram v{payload}, de ez az alkalmazás v{app}",
helper_mismatch_send: "Segédprogram küldése",
helper_mismatch_body_v3: "A PS5-ön magán nincs teendő: nyomd meg a „Segédprogram küldése” gombot, és ez az app elküldi a konzolra a hozzá illő segédprogramot. Addig az újabb verzió javításai és funkciói nem működnek.",

"joberr.direct_staged_file_missing": "Ez a feltöltés már befejeződött, így nem maradt semmi közzétehető — és a fájl a PS5-ön most hiányzik vagy rossz méretű. Töltsd fel újra, és válaszd a Felülírást a Folytatás helyett.",
"joberr.direct_tx_corrupt": "A PS5 protokollhibát észlelt ebben az átvitelben. Indítsd újra a payloadot a Payload küldése fülről, és próbáld újra.",
"joberr.direct_writer_io_error": "A PS5-nek elfogyott a szabad helye (vagy egy külső meghajtó leválasztódott) a fájl írása közben. Szabadíts fel helyet a célmeghajtón, és kattints az Újrapróbálkozásra — a feltöltés onnan folytatódik, ahol abbamaradt.",
"joberr.fs_delete_path_not_allowed": "A PS5 megtagadta a hozzáférést ehhez az útvonalhoz. Használj /data/, /user/ vagy egy csatolt /mnt/ext*, /mnt/usb* útvonalat.",
"joberr.fs_read_path_not_allowed": "Ez a fájl egy normál esetben letiltott, csak olvasható rendszerpartíción van. Kapcsold be a Beállítások → \"Rendszerfájlok letöltésének engedélyezése\" opciót, hogy letölthess a /system, /system_data és más védett útvonalakról.",
"joberr.fs_write_failed": "A PS5 nem tudott írni a célra az átvitel közben — leggyakrabban azért, mert megtelt a meghajtó, vagy egy külső meghajtó leválasztódott. Ellenőrizd a szabad helyet / csatlakoztasd újra a meghajtót, majd kattints az Újrapróbálkozásra (a feltöltés onnan folytatódik, ahol abbamaradt).",
"joberr.fs_write_failed_no_space": "A célmeghajtónak elfogyott a helye (vagy a fájl túl nagy ahhoz a fájlrendszerhez). Szabadíts fel helyet a PS5-ön / külső meghajtón — vagy válassz másik célt —, majd kattints az Újrapróbálkozásra.",
"joberr.packed_unsupported": "A PS5 segédprogramja elutasított egy csomagolt átvitelt — ez elavult payloaddal fordul elő, amikor egy mappafeltöltés egyetlen kicsi fájlra szűkül (pl. egy sok apró fájlt tartalmazó játék Folytatásánál). Frissítsd a ps5upload-ot a legújabb verzióra, küldd újra a payloadot a Payload küldése fülről, majd próbáld újra.",
"joberr.preflight_insufficient_space": "A célmeghajtón nincs elég szabad hely ehhez a fájlhoz. Szabadíts fel helyet a PS5-ön (Beállítások → Tárhely) vagy válassz másik célt, majd kattints az Újrapróbálkozásra.",
"joberr.size_mismatch": "Az átvitel megszakadt, mielőtt befejeződött volna — egy fájl hiányos a PS5-ön, ezért nem lett közzétéve (a régi másolatod, ha volt, érintetlen). Ez általában azt jelenti, hogy a PS5 pihenő módba lépett vagy áramot vesztett feltöltés közben. Tartsd ébren a konzolt (Beállítások → Rendszer → Energiatakarékosság → PS5 kikapcsolásáig eltelő idő beállítása), majd futtasd újra ezt az elemet — a Folytatás most csak a hiányzó fájlokat küldi újra, vagy válaszd a Felülírást egy tiszta másolathoz.",
"joberr.ava1_stalled": "Az átvitel nem halad tovább (a forrás nem küld több adatot). Próbáld újra; ha ismétlődik, ellenőrizd a forrásmeghajtót vagy a hálózati megosztást.",
"joberr.tx_table_full": "Túl sok egyidejű átvitel van folyamatban a PS5-ön. Várj, amíg néhány befejeződik, vagy indítsd újra a payloadot.",
"joberr.zip_unsupported": "Ez a .zip olyasmit használ, amit a feltöltő nem tud folyamként átvinni (titkosítás, a Deflate-től vagy Stored-tól eltérő tömörítési mód, vagy nem biztonságos vagy ismétlődő fájlútvonal). Csomagold ki a számítógépeden, és töltsd fel a mappát.",
"joberr.sevenz_unsupported": "Ez a .7z olyan tömörítési módot vagy funkciót használ, amit a feltöltő nem tud folyamként átvinni. Csomagold ki a számítógépeden, és töltsd fel a mappát.",
"joberr.sevenz_unsupported_layout": "Ebben a .7z-ben egyetlen tömör blokkon belül mappák vagy üres fájlok vannak a fájlok között, ezt az elrendezést a feltöltő nem tudja folyamként átvinni. Csomagold újra 7-Zippel, vagy csomagold ki, és töltsd fel a mappát.",
"joberr.rar_unsupported": "Ebben a .rar-ban ismétlődő vagy nem biztonságos fájlútvonalak vannak, vagy olyan funkció, amit a feltöltő nem tud folyamként átvinni. Csomagold ki a számítógépeden, és töltsd fel a mappát.",
"pkg.patch_did_not_apply": "A PS5 elfogadta ezt a frissítést, majd nem csinált vele semmit — a játék még mindig az előző verzióján van. Ez azt jelenti, hogy a konzol nem tudta a frissítést párosítani a telepített alapjátékoddal. Telepítsd újra az alapjátékot a ps5upload-on keresztül az ehhez a frissítéshez tartozó alapcsomagból (válaszd a Felülírást), majd alkalmazd újra a frissítést.",
"pkglib.updateBaseUnknown.title": "Előfordulhat, hogy ez a frissítés nem alkalmazódik",
"pkglib.updateBaseUnknown.installAnyway": "Telepítés mindenképp",
"pkglib.updateBaseUnknown.body": "A(z) {id} telepítve van, de nem egy olyan alapcsomagból, amelyet a ps5upload telepített — így előfordulhat, hogy a PS5 nem tudja ehhez párosítani a frissítést. Ha ez történik, a konzol sikert jelent, de csendben semmit sem változtat. Ha a játék utána is a régi verzióján marad, telepítsd a hozzáillő alapcsomagot a ps5upload-on keresztül (válaszd a Felülírást), majd alkalmazd újra ezt a frissítést.",
"pkg.patch_regressed": "Ennek a frissítésnek az újbóli alkalmazása eltávolította azt — a játék visszaállt az alapverziójára. A PS5 telepítője az újra alkalmazott frissítést visszavonandóként kezeli. Alkalmazd még egyszer a frissítést, hogy visszakerülj a frissített verzióra, és kerüld el egy olyan frissítés újratelepítését, amellyel a játék már rendelkezik.",
"sdk_patch_libc": "A libc.prx patchelése is",
"sdk_patch_libc_hint": "Egy kompatibilitási módosítás, amelyre néhány backportolt játéknak szüksége van — és amely másoknál megakadályozza az indulást. Hagyd kikapcsolva, kivéve ha a játék nélküle nem indul el.",
backport_action: "Backport",
backport_auto: "Készletek automatikus kipróbálása",
backport_auto_hint: "Telepít egy készletet, elindítja a játékot, és ha nem indul el, visszavonja, és a következőre lép — amíg egy nem működik, vagy elfogynak a készletek.",
backport_auto_running: "{label} kipróbálása — {index}. készlet a(z) {total}-ból…",
backport_auto_stop: "Leállítás",
backport_auto_stopping: "Az aktuális készlet befejezése…",
backport_auto_stopped: "Leállt {tried} készlet kipróbálása után.",
backport_auto_exhausted: "Minden elérhető készlet ki lett próbálva — egyik sem indította el ezt a játékot.",
backport_auto_worked: "A(z) {label} működik — a játék elindult.",
backport_title: "{name} backportolása",
backport_overlay_unavailable: "A könyvtár-overlay nem érhető el",
backport_overlay_external: "Egy külső BackPork/unionfs overlay már aktív.",
