backport_verify_unpatched: "Ez a cím nincs backportolva",
backport_verify_unpatched_body: "Az ebootja még mindig az eredeti SDK verziót hordozza, így nem tud futni ezen a firmware-en, bármilyen könyvtár is van telepítve — a könyvtárkészlet nem a probléma. Futtasd újra a backportot; ha ez ismétlődik, az SDK patch nem érvényesül.",
backport_no_larger: "Ez a játék olyan könyvtárakat igényel, amelyek egyik készletedben sincsenek. Importálj egy teljesebb csomagot, vagy szkennelj be egy másik konzolt.",
