"joberr.ava1_commit_exists": "A fájl feltöltődött, de nem tehető közzé, mert a cél már létezik. Válaszd a Felülírás lehetőséget a cseréhez, vagy válassz másik célt.",
"joberr.ava1_cross_device": "A cél másik meghajtón van, mint az átmeneti terület, ezért a PS5 nem tudta áthelyezni a fájlt. Válassz célt ugyanazon a meghajtón, vagy előbb tölts fel a belső meghajtóra.",
"joberr.ava1_wrong_console": "Az ezen a címen lévő eszköz nem az a PS5, amellyel az alkalmazás párosítva van. Ellenőrizd a címet, vagy párosítsd újra ezt a konzolt.",
"joberr.ava1_no_identity": "Az alkalmazásnak még nincs párosítási azonosítója. Párosítsd a PS5-tel a Kapcsolat képernyőn, majd próbáld újra.",
"joberr.zip_read_error": "A .zip nem olvasható (a fájl vagy a meghajtója eltűnhetett olvasás közben). Ellenőrizd, hogy a forrás még csatlakoztatva van, majd kattints az Újra gombra.",
"joberr.ava1_zip_corrupt": "Ez a .zip nem olvasható: sérült vagy hiányos. Töltsd le vagy hozd létre újra, majd próbáld újra.",
"joberr.ava1_7z_corrupt": "Ez a .7z nem olvasható: sérült vagy hiányos. Töltsd le vagy hozd létre újra, majd próbáld újra.",
"joberr.ava1_7z_encrypted": "Ez a .7z titkosított, ezért nem streamelhető. Csomagold ki a számítógépeden, és töltsd fel helyette a mappát.",
"joberr.ava1_7z_unsafe_path": "Ez a .7z nem biztonságos fájlútvonalat tartalmaz (kilép a saját mappájából). Csomagold ki a számítógépeden, és töltsd fel helyette a mappát.",
"joberr.rar_password": "Ehhez a .rar-hoz jelszó kell, vagy a megadott jelszó hibás volt. Add meg a helyes jelszót, majd próbáld újra.",
"joberr.rar_corrupt": "Ez a .rar sérült, vagy egyes részei hiányoznak vagy rossz sorrendben vannak. Győződj meg róla, hogy minden rész megvan, majd próbáld újra.",
"joberr.ava1_copy_lost": "A PS5 elvesztette ennek a másolásnak a nyomát (a segédprogram újraindult vagy megszakadt a kapcsolat). Kattints az Újra gombra az újrakezdéshez.",
"joberr.ava1_copy_failed": "A PS5 nem tudta befejezni a másolást. Ellenőrizd a szabad helyet, és hogy a forrás és a cél még elérhető-e, majd próbáld újra.",
"joberr.ava1_local_io": "Ez a számítógép nem tudta kiírni a letöltött fájlt. Ellenőrizd a célmappa jogosultságait és szabad helyét, majd próbáld újra.",
"joberr.ava1_bad_manifest": "A PS5 olyan fájllistát küldött, amelyet ez az alkalmazás nem értett. Frissítsd a segédprogramot és az alkalmazást ugyanarra a verzióra, majd próbáld újra.",
"joberr.helper_not_ava1": "A PS5 segédprogramja nem fut. Küldd el a Kapcsolat képernyőről (vagy használd a Segédprogram frissítése gombot, ha a szalag felajánlja), majd próbáld újra.",
"joberr.helper_not_ava1_web": "A PS5 segédprogramja nem fut. Ez a webes felület nem tudja elküldeni: indítsd el a ps5upload payloadot a konzolon a szokásos payload-betöltőddel (vagy használd a Segédprogram frissítése gombot, ha a szalag felajánlja), majd próbáld újra.",
"joberr.not_paired": "Ez a PS5 még nem fogadta el ezt az alkalmazást. Párosítsd őket (Párosítás… gomb), majd próbáld újra.",
"joberr.helper_starting": "A PS5 segédprogramja még indul. Várj néhány másodpercet, majd próbáld újra.",
"joberr.ava1_failed": "A PS5 segédprogramja elindult, de az átviteli szervere nem. Indítsd újra a konzolt, majd próbáld újra.",
