"netdoctor.other_work.busy.detail": "{count} átvitel vagy feladat fut. Osztoznak a hálózaton és a PS5-ön, ezért mind lassabb.",
"netdoctor.other_work.busy.fix": "Várd meg, amíg befejeződnek, vagy állítsd le azokat, amelyekre most nincs szükséged, aztán ellenőrizz újra.",
"netdoctor.other_work.busy.title": "Az alkalmazás más feladatai osztoznak a kapcsolaton",
"netdoctor.other_work.idle.detail": "Az alkalmazásban nincs más átvitel vagy feladat, amely versengene a kapcsolatért.",
