trace_title: "Mérés játék közben",
trace_measuring: "Mérés",
trace_what: "Olyan LZ4 játékképfájlhoz, amely úgy tölt be, ahogy a játék játszik. Az ampr_emu mérő változata minden fájlt feljegyez, amit a játék olvas játék közben; az ezekből a menetekből épített profil fájlonként választ blokkméretet, elrendezést és gyorsítótár-méretet egyetlen becslés helyett. A Convert ezt használja, ha LZ4 képfájlt készítesz ebből a játékból.",
