fs_send_dial_hint: "Hagyd üresen, hogy a konzol saját címét tárcsázza. ps5-tailscale esetén állíts be helyi továbbítást a küldő konzolon (állapotoldala: 127.0.0.1:19120 → a másik konzol:9120), és írd ide: 127.0.0.1:19120. Hogy ki küldhet, azt a konzolok kulcsai és egy egyszer használatos jegy döntik el, nem a cím.",
