sendpayload_probe_invalid_ext: "A payloadnak .elf, .bin, .js, .lua vagy .jar fájlnak kell lennie.",
sendpayload_probe_no_signature: "Nem található PS5Upload aláírás — csak akkor használd, ha megbízol ebben a payloadban.",
