settings_schedule_label_placeholder_v2: "Címke (pl. mentések biztonsági mentése)",
settings_updates_browser_note: "Ezt a weboldalt a ps5upload motor szolgálja ki, és vele együtt frissül: töltsd le az új Docker image-et (vagy frissítsd a motort a kiszolgálón), és indítsd újra.",
"show_file_list_hint_v2": "A feltöltés alatt álló fájlok listázása a folyamatjelző alatt. Kapcsold ki, ha a lista zavaró több ezer fájlos mappáknál — az összesített haladás, a sebesség és a hátralévő idő így is látszik.",
show_file_list_v2: "Fájllista megjelenítése feltöltés közben",
stats_description_v2: "Összesítések az ehhez a konzolhoz megjelenített műveletekről. Az alkalmazás az utolsó {count} műveletet tartja meg, így a régebbiek nem számítanak bele. Helyi előzményekből számolva; semmi sem hagyja el a gépedet.",
status_keep_awake_tooltip_v2: "Az ébren tartás „Mindig, amíg csatlakoztatva van” módra van állítva — a csatlakoztatott konzolok nem lépnek automatikusan pihenő módba, amíg az alkalmazás nyitva van. Módosítás: Beállítások → Konzol.",
update_idle_v2: "Még nincs ellenőrizve. Bekapcsolt automatikus ellenőrzés mellett az alkalmazás indításkor a háttérben ellenőriz, legfeljebb naponta egyszer.",
upload_auto_resume_hint_browser: "Ha egy feltöltés átvitel közben megszakad, folytatja onnan, ahol abbamaradt, amint a PS5 segédprogramja ismét válaszol, és néhányszor újrapróbálkozik, mielőtt feladja. Ez az oldal maga nem tudja újraküldeni a segédprogramot: ha a PS5 újraindult, előbb küldd el újra. A végzetes problémák, például ha a PS5-ön elfogy a hely, továbbra is azonnal leállítják. Alapértelmezetten bekapcsolva.",
upload_wake_for_uploads: "PS5 felébresztése egy várakozó feltöltéshez",
upload_wake_for_uploads_hint: "Ha egy feltöltés pihenő módban lévő PS5-re vár, ébresztőjelet küld neki, és folytatja, amint a segédprogramja újra fut. Csak olyan konzolnál, amelynél az ébresztés be van állítva a Kapcsolat képernyőn. Alapértelmezés szerint be.",
upload_picker_from_ps5_hint: "Másik PS5-ről másolsz? Jelöld ki a fájlokat a Fájlrendszerben, és válaszd a Küldés másik konzolra lehetőséget.",
