backup_explain_v2: "Fájlokat másol egy pillanatképbe a konzol saját tárhelyén, hogy később visszatehesd őket. Válassz egy gyakori elemet lent, vagy írd be a saját útvonaladat.",
backup_limit_depth: "A kiválasztottnál {n} szintnél mélyebben lévő mappák kimaradnak.",
backup_limit_flatten: "A fájlok az útvonalukon tárolódnak, minden / helyett _ karakterrel, így két különböző útvonal ugyanazt a nevet kaphatja (a/b_c és a_b/c), és csak az egyik marad meg.",
backup_limit_keep: "Minden névből csak a legújabb {n} pillanatkép marad meg; egy újabb készítése törli a legrégebbit.",
backup_subtitle_v3: "Másolj fájlokat és mappákat egy magán a PS5-ön tárolt pillanatképbe, és tedd vissza őket később. Erre a számítógépre semmi sem másolódik. A játékmentésekhez használd a Mentésadatokat.",
beta_features_hint_v2: "Fejlesztés alatt álló képernyőket ad az oldalsávhoz, ha vannak ilyenek. Használhatók, de még nem megbízhatók, és változhatnak vagy eltűnhetnek.",
bringup_desc_v2: "Minden indításkor, miután a lejátszási listáid be vannak állítva a Payloadok alatt: lefuttatja a bring-up lejátszási listádat (kstuff, ShadowMount+…), elküldi a segédprogramot ugyanúgy, mint a 2. lépés, majd lefuttatja az automatikus betöltő lejátszási listádat.",
