install_hint_setup_exe: "Megnyílt a telepítő: kövesd a lépéseit, és helyben frissíti a PS5Uploadot.",
install_path_fallback_hint: "Végső megoldás egy már a PS5-ön lévő csomaghoz, ha a PS5 a saját tárhelyéről elutasítja, és erről a számítógépről sem tudja letölteni. Csak nem telepített alapjátékhoz használatos, így semmit sem távolíthat el. Nem igazolt: a 11.20-as firmware-en működött, a 13.60-on elutasítják. Ha kipróbálod, kérjük, jelezd, hogy működött-e.",
install_path_fallback_label: "Telepítés fájlútvonal alapján, ha a PS5 nem éri el ezt a számítógépet",
"installed_fix_permissions": "Jogosultságok javítása: a játék mappája legyen olvasható és futtatható a PS5 számára (chmod 777)",
