"minion_open_here": "Megnyitás itt",
"minion_remove_note": "Az eltávolítás kikapcsolja a Miniont, és törli, amit a PS5-ön tárol: a Fájlok kedvenceit és legutóbbi mappáit, a játékkönyvtár gyorsítótárát és a kontrollernaplót. A hálózati megosztások, a csalások és a biztonsági mentések megmaradnak; a PC-s alkalmazás is használja őket.",
