"connection_send_payload_moved": "Másik payloadot küldenél (kstuff, etaHEN, bármilyen .elf)? Ez a Payloadok → Payload küldése alatt van. Ez a képernyő csak a PS5Upload segédprogramot küldi.",
"connection_send_payload_open": "Payload küldése megnyitása",
"upload_elf_title": "Ez egy payload (.elf), nem játék",
"upload_elf_body": "A feltöltés csak átmásolja a fájlt. A ShadowMount+ a játékmappákat (eboot.bin és sce_sys fájllal) és a játékképeket veszi fel, .elf fájlt soha, így nem jelenik meg a kezdőképernyőn. A futtatásához inkább küldd el a konzol betöltőjének. Feltölteni olyan homebrew alkalmazást érdemes, amely .ffpkg vagy .exfat képként, vagy eboot.bin fájlt tartalmazó mappaként érkezik.",
"netdoctor.hint.below_test": "Ez a feltöltés {speed} sebességgel fut, jóval a sebességteszt által mért {expected} alatt.",
"netdoctor.hint.runs_at": "Ez a feltöltés {speed} sebességgel fut.",
"netdoctor.hint.cause_source": "Nem a hálózat fogja vissza, hanem a fájlok olvasása ezen a számítógépen: egy USB-meghajtó vagy merevlemez, egy hálózati megosztás (NAS) vagy egy archívum kibontása lassabb a kapcsolatnál. Ha a játékot előbb egy belső SSD-re másolod, vagy az archívum fájljait kibontva töltöd fel, teljes sebességet kapsz.",
"netdoctor.hint.cause_disk": "Nem a hálózat fogja vissza, hanem a PS5 meghajtója: egy külső USB-meghajtó, egy majdnem tele meghajtó vagy több ezer kis fájl (mindegyik saját időt igényel) lassabban ír, mint amit a kapcsolat szállít. Egy játékkép (.ffpkg vagy .exfat) egyetlen fájlként megy át.",
"netdoctor.hint.cause_workers": "A PS5 még írja, amit kapott, nem a hálózatra vár. Sok kis fájlnál mindegyik saját időt igényel; egy játékkép (.ffpkg vagy .exfat) egyetlen fájlként megy át.",
"netdoctor.hint.cause_cap": "A feltöltési sebességkorlát fogja vissza (kb. {cap} MiB/s, ezen a képernyőn és a Beállításokban). Állítsd 0-ra a megszüntetéséhez.",
"profile.np.confirm_body_v2": "Az np-fake-signin PlayStation Network bejelentkezési fájlokat és beállításokat ír a PS5-re {user} számára. Semmi nem megy a Sonynak. Utána indítsd újra a PS5-öt.",
"profile.np.side_effect": "Ismert mellékhatás: utána egyes konzolok minden játék megnyitása előtt a „PS5 konzolkorlátozások ideiglenes kikapcsolását” kérik, és a Beállítások > Felhasználók és fiókok > Egyéb > Kijelentkezés szürke maradhat. Az alkalmazás előbb másolatot tart a PS5-ön mindenről, amit az np-fake-signin megváltoztat, így a Bejelentkezés visszavonása itt visszaállítja.",
"profile.np.backing_up": "A fiók jelenlegi beállításainak másolata a PS5-re kerül…",
"profile.np.backup_failed": "A PS5 nem tudott másolatot tartani a fiók beállításairól, ezért az np-fake-signin nem futott le. Cseréld le a segédprogramot erre az alkalmazásverzióra, és próbáld újra. ({error})",
"profile.np.step_restart_v2": "Indítsd újra a PS5-öt. Későbbi visszavonáshoz nyomd meg itt a Bejelentkezés visszavonása gombot, majd indítsd újra.",
"profile.np.undo": "Bejelentkezés visszavonása",
"profile.np.undo_hint": "A fiók bejelentkezés előtti beállításainak másolata a PS5-ön van; ez visszaállítja.",
"profile.np.undo_confirm_title": "Visszavonod a bejelentkezést?",
"profile.np.undo_confirm_body": "Visszaállítja {user} beállításait és fájljait az np-fake-signin futtatása előtti állapotra. Utána indítsd újra a PS5-öt. A bejelentkezett fiókot igénylő funkciók, köztük a Remote Play, az újbóli bejelentkezésig nem biztos, hogy megnyílnak.",
"profile.np.undoing": "A beállítások visszaállítása…",
"profile.np.undone": "Visszaállítva ({count} beállítás és fájl). A befejezéshez indítsd újra a PS5-öt.",
"profile.np.no_backup": "Ezen a fiókon az np-fake-signin sablonbeállításai vannak (születési dátum 1983-04-12, az offline felnőtt jelző kikapcsolva), és erről a PS5-ről hiányzik a korábbi másolat, ezért az alkalmazás nem tudja visszavonni. Ha a PS5 most a játékok megnyitása előtt a konzolkorlátozások ideiglenes kikapcsolását kéri: Beállítások > Család és szülői felügyelet > PS5 konzolkorlátozások (jelkód 0000, hacsak nem változtattad meg), és ott oldd fel a korlátozásokat.",
