"rp_touch_off": "Soha",
"rp_controls_hint": "Kontroller is működik: csatlakoztasd vagy párosítsd ezzel az eszközzel. A Shift + húzás a képen egy ujj az érintőpadon.",
"rp_settings": "Beállítások",
"rp_running_elsewhere": "A Játék fut ezen: {name}",
"rp_show_here": "Megjelenítés itt",
"rp_running_elsewhere_body": "Másik ablakból vagy az oldal újratöltése előtt indult, és még fut.",
"rpg_user_title": "Jelentkezz be egy felhasználóval a PS5-ön",
"rpg_user_body": "A konzolon válaszd ki a felhasználót, akivel játszani fogsz. Senkinek nem kell a képernyőn maradnia, de a felhasználónak bejelentkezve kell lennie. Bejelentkezési kód nélküli felhasználót használj: a kód megállítja az automatikus bejelentkezést, amikor a konzol felébred.",
"rpg_account_title": "Adj fiókazonosítót ennek a felhasználónak",
"rpg_account_body": "A Remote Play fiókazonosítóval párosodik. A PlayStation Networkhöz kapcsolt felhasználónak már van; offline felhasználónak a fenti Felhasználók részben kell beállítani egyet (bármilyen azonosító jó; írd fel, az ezután készült mentések hozzá kötődnek).",
"rpg_signin_title": "Jelentkeztesd be a fiókot a PlayStation Networkbe (offline)",
"rpg_signin_body": "A PS5 csak bejelentkezett fióknak engedi a Remote Play használatát. Ha a konzol saját Remote Play-beállítása szürke, futtasd az alábbi offline bejelentkezést (semmi nem megy a Sonynak), majd indítsd újra a PS5-öt. Visszavonható.",
"rpg_signin_fix": "Ugrás a bejelentkezéshez",
"rpg_service_title": "Kapcsold be a Remote Playt",
"rpg_service_body": "Beállítások › Rendszer › Remote Play › Remote Play bekapcsolása. Az alkalmazás be tudja kapcsolni helyetted, és 10.00-s vagy újabb firmware-en ehhez a felhasználóhoz is engedélyezni tudja.",
"rpg_rest_title": "Engedd, hogy a PS5 felébreszthető legyen pihenő módból",
"rpg_rest_body": "Beállítások › Rendszer › Energiatakarékosság › Pihenő módban elérhető funkciók: kapcsold be a „Kapcsolat fenntartása az internettel” és a „PS5 hálózatról való bekapcsolásának engedélyezése” lehetőséget. Nélkülük a pihenő módban lévő konzol nem ébreszthető fel, és a hálózata néhány másodperc után elalszik. Ezeket csak a konzol tudja megjeleníteni.",
"rpg_pair_title": "Párosítsd ezt az alkalmazást a konzollal",
"rpg_pair_body": "Kapcsolat › Felébresztés és bejelentkezés › Beállítás. Egy kattintással regisztrálod ezt az alkalmazást a PS5-ön (mint a PS Remote Play alkalmazás párosításakor), a kulcsai pedig ezen a számítógépen maradnak. A streamelés, az ébresztés és a bejelentkezés mind ezeket használja; a konzol visszaállítása vagy a felhasználó cseréje után csináld meg újra.",
"rpg_play_title": "Játék",
"rpg_play_body": "Nyisd meg a Remote Playt, és nyomd meg az Indítás gombot: az alkalmazás felébreszti a konzolt, ha pihen, bejelentkezik és streamel. Játssz a számítógéphez csatlakoztatott kontrollerrel, billentyűzettel vagy érintéssel. Ha inkább a Sony PS Remote Play alkalmazását vagy a chiaki-ng-t használnád, kérj lent egy PIN-t, és ott add meg.",
"rpg_play_fix": "Remote Play megnyitása",
"rpg_title": "Remote Play beállítása",
"rpg_progress": "{n} ellenőrzött lépésből {done} kész",
"rpg_on_console": "ellenőrizd a konzolon",
"rpg_trouble": "Ha még mindig nem működik",
"rpg_t_start_q": "A Start szürke a Játék képernyőn.",
"rpg_t_start_a": "Ez az alkalmazás még nincs párosítva azzal a konzollal: végezd el a 6. lépést (Kapcsolat › Felébresztés és bejelentkezés › Beállítás).",
"rpg_t_pair_q": "A párosítás beállítása szerint nincs bejelentkezett felhasználó aktivált fiókkal.",
"rpg_t_pair_a": "1. és 2. lépés: jelentkezz be egy felhasználóval a PS5-ön, adj neki fiókazonosítót, majd próbáld újra.",
"rpg_t_grey_q": "A PS5 saját Remote Play-beállítása szürke.",
"rpg_t_grey_a": "A fiók nincs bejelentkezve a PlayStation Networkbe. Futtasd az offline bejelentkezést (3. lépés), és indítsd újra a PS5-öt.",
"rpg_t_wake_q": "A konzol nem ébred fel, vagy felébred, de a felhasználóválasztó képernyőn marad.",
"rpg_t_wake_a": "Ellenőrizd az 5. lépést a konzolon. A bejelentkezési kóddal rendelkező felhasználó megállítja az automatikus bejelentkezést. Ha a konzolt visszaállították vagy a felhasználó megváltozott, állítsd be újra a párosítást (6. lépés).",
"rpg_t_black_q": "A kép fekete marad, akadozik, vagy recseg a hang.",
"rpg_t_black_a": "Használj vezetékes kapcsolatot vagy 5 GHz Wi-Fi-t a PS5-höz és ehhez a számítógéphez, és próbáld ki a 720p-t vagy a 30 fps-t a Remote Play beállításaiban. A számítógép tűzfalának engedélyeznie kell az alkalmazást a helyi hálózaton (a Remote Play a 9295–9304 TCP- és UDP-portokat használja). Böngészőben friss Chrome-ot, Edge-et vagy Safarit használj: a képhez WebCodecs kell.",
"rpg_t_busy_q": "Azt írja, hogy a PS5 még zárja az előző munkamenetet, vagy egy másik konzol streamel.",
"rpg_t_busy_a": "Egyszerre egy konzol streamel, és a PS5-nek egy munkamenet vége után legfeljebb 30 másodperc kell. Állítsd le a másik streamet, várj egy kicsit, majd nyomd meg újra az Indítás gombot.",
"rpg_t_restrict_q": "Az offline bejelentkezés után a játékok a konzolkorlátozások kikapcsolását kérik.",
"rpg_t_restrict_a": "Használd ezen az oldalon a Bejelentkezés visszavonása gombot, és indítsd újra, vagy oldd fel a korlátozást itt: Beállítások › Család és szülői felügyelet › PS5 konzolkorlátozások (jelkód 0000, hacsak nem változtattad meg).",
